suppressMessages(library(dplyr))
u <- readRDS("data/federal_elections/county_level/final/federal_cty_unharm.rds")
m <- readRDS("data/federal_elections/municipality_level/final/federal_muni_unharm.rds")
cat("muni ags nchar\n"); print(table(nchar(m$ags)))
mc <- m %>% mutate(cty=substr(ags,1,5)) %>% group_by(cty, year=election_year) %>% summarise(across(c(eligible_voters,number_voters,valid_votes,invalid_votes,spd,cdu,csu,afd,gruene,fdp,linke_pds), ~sum(.x,na.rm=T)), n_muni=n(), .groups="drop")
j <- full_join(u %>% select(ags,year,eligible_voters,number_voters,valid_votes,invalid_votes,spd,cdu,csu,afd,gruene,fdp,linke_pds), mc, by=c("ags"="cty","year"), suffix=c(".c",".m"))
cat("only in cty:", sum(is.na(j$n_muni)), " only in muni:", sum(is.na(j$eligible_voters.c)),"\n")
print(j %>% filter(is.na(n_muni)) %>% count(year))
print(j %>% filter(is.na(eligible_voters.c)) %>% count(year))
b <- j %>% filter(!is.na(n_muni), !is.na(eligible_voters.c)) %>% mutate(dv=number_voters.m/number_voters.c-1, de=eligible_voters.m/eligible_voters.c-1, dval=valid_votes.m/valid_votes.c-1)
print(b %>% group_by(year) %>% summarise(n=n(), tot_c=sum(number_voters.c), tot_m=sum(number_voters.m), ratio=tot_m/tot_c, n_off1=sum(abs(dv)>0.01,na.rm=T), n_offe1=sum(abs(de)>0.01,na.rm=T), maxabs=max(abs(dv),na.rm=T)) %>% as.data.frame)
saveRDS(b, file.path(Sys.getenv("D"), "b.rds"))
